/* DAWAH X — ahmad, অধ্যায় 117 · খণ্ড 117 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][117]=[[23201,23201,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ مَنْ رَفَقَ بِأُمَّتِي فَارْفُقْ بِهِ وَمَنْ ‏ ‏شَقَّ ‏ ‏عَلَيْهِمْ فَشُقَّ عَلَيْهِ ‏","","",""],[23202,23202,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا سَلَّمَ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[23203,23203,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّاسُ عُمَّالَ أَنْفُسِهِمْ فَكَانُوا يَرُوحُونَ كَهَيْئَتِهِمْ فَقِيلَ لَهُمْ لَوْ اغْتَسَلْتُمْ ‏","","",""],[23204,23204,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدَعُ أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ عَلَى حَالٍ ‏","","",""],[23205,23205,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ تَكُونُ لَهُ سَاعَةٌ مِنْ اللَّيْلٍ يَقُومُهَا فَيَنَامُ عَنْهَا إِلَّا كُتِبَ لَهُ أَجْرُ صَلَاتِهِ وَكَانَ نَوْمُهُ عَلَيْهِ صَدَقَةً تُصُدِّقَ بِهِ عَلَيْهِ ‏","","",""],[23206,23206,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَتْ يَنَامُ أَوَّلَهُ وَيَقُومُ آخِرَهُ ‏","","",""],[23207,23207,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَبْغَضَ الرِّجَالِ إِلَى اللَّهِ ‏ ‏الْأَلَدُّ ‏ ‏الْخَصِمُ ‏","","",""],[23208,23208,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏عَنْ ‏ ‏مَوْلىً لِعَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا نَظَرْتُ إِلَى فَرْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ أَوْ مَا رَأَيْتُ فَرْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ ‏","","",""],[23209,23209,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏وَسُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا أَنْ تَسْتَرْقِيَ مِنْ ‏ ‏الْعَيْنِ ‏","","",""],[23210,23210,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَسْتَخْلِفْ أَحَدًا وَلَوْ كَانَ مُسْتَخْلِفًا أَحَدًا لَاسْتَخْلَفَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَوْ ‏ ‏عُمَرَ ‏","","",""],[23211,23211,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏رَبَاحٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَبِثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتَّةَ أَشْهُرٍ يَرَى أَنَّهُ يَأْتِي وَلَا يَأْتِي فَأَتَاهُ مَلَكَانِ فَجَلَسَ أَحَدُهُمَا عِنْدَ رَأْسِهِ وَالْآخَرُ عِنْدَ رِجْلَيْهِ فَقَالَ أَحَدُهُمَا لِلْآخَرِ مَا بَالُهُ قَالَ ‏ ‏مَطْبُوبٌ ‏ ‏قَالَ مَنْ ‏ ‏طَبَّهُ ‏ ‏قَالَ ‏ ‏لَبِيدُ بْنُ الْأَعْصَمِ ‏ ‏قَالَ فِيمَ قَالَ فِي مُشْطٍ ‏ ‏وَمُشَاطَةٍ ‏ ‏فِي جُفِّ ‏ ‏طَلْعَةِ ‏ ‏ذَكَرٍ فِي ‏ ‏بِئْرِ ذَرْوَانَ ‏ ‏تَحْتَ ‏ ‏رَاعُوفَةٍ ‏ ‏فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَوْمِهِ فَقَالَ أَيْ ‏ ‏عَائِشَةُ ‏ ‏أَلَمْ تَرَيْنَ ‏ ‏أَنَّ اللَّهَ أَفْتَانِي فِيمَ اسْتَفْتَيْتُهُ فَأَتَى الْبِئْرَ فَأَمَرَ بِهِ فَأُخْرِجَ فَقَالَ هَذِهِ الْبِئْرُ الَّتِي أُرِيتُهَا وَاللَّهِ كَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ وَكَأَنَّ رُءُوسَ نَخْلِهَا رُءُوسُ الشَّيَاطِينِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَوْ أَنَّكَ كَأَنَّهَا تَعْنِي أَنْ يَنْتَشِرَ قَالَ أَمَا وَاللَّهِ قَدْ عَافَانِي اللَّهُ وَأَنَا أَكْرَهُ أَنْ أُثِيرَ عَلَى النَّاسِ مِنْهُ شَرًّا ‏","","",""],[23212,23212,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُحِرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَنَّهُ لَيُخَيَّلُ لَهُ أَنَّهُ يَفْعَلُ الشَّيْءَ وَمَا يَفْعَلُهُ حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ وَهُوَ عِنْدَهَا دَعَا اللَّهَ عَزَّ وَجَلَّ وَدَعَاهُ ثُمَّ قَالَ أَشَعَرْتِ ‏ ‏أَنَّ اللَّهَ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ قُلْتُ وَمَا ذَاكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنِي رَجُلَانِ فَجَلَسَ أَحَدُهُمَا عِنْدَ رَأْسِي وَالْآخَرُ عِنْدَ رِجْلَيَّ ثُمَّ قَالَ أَحَدُهُمَا لِصَاحِبِهِ مَا وَجَعُ الرَّجُلِ قَالَ ‏ ‏مَطْبُوبٌ ‏ ‏قَالَ مَنْ ‏ ‏طَبَّهُ ‏ ‏قَالَ ‏ ‏لَبِيدُ بْنُ الْأَعْصَمِ ‏ ‏الْيَهُودِيُّ قَالَ فِي مَاذَا قَالَ فِي مُشْطٍ ‏ ‏وَمُشَاطَةٍ ‏ ‏وَجُفِّ ‏ ‏طَلْعَةِ ‏ ‏ذَكَرٍ قَالَ فَأَيْنَ هُوَ قَالَ فِي ‏ ‏بِئْرِ ذَرْوَانَ ‏ ‏فَذَهَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْبِئْرِ فَنَظَرَ إِلَيْهَا وَعَلَيْهَا نَخْلٌ ثُمَّ رَجَعَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ وَاللَّهِ لَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ وَلَكَأَنَّ نَخْلَهَا رُءُوسُ الشَّيَاطِينِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ فَأَحْرِقْهُ قَالَ لَا أَمَّا أَنَا فَقَدْ عَافَانِي اللَّهُ عَزَّ وَجَلَّ وَخَشِيتُ أَنْ أُثَوِّرَ عَلَى النَّاسِ مِنْهُ شَرًّا ‏","","",""],[23213,23213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَحْدِي قَرَأَهُ عَلَيَّ وَأَنَا أَسْمَعُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[23214,23214,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِينِي ‏ ‏الْعَرْقَ ‏ ‏فَأَتَعَرَّقُهُ ثُمَّ يَأْخُذُهُ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ ‏ ‏وَيُعْطِينِي الْإِنَاءَ فَأَشْرَبُ ثُمَّ يَأْخُذُهُ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ ‏","","",""],[23215,23215,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا جُعِلَ الطَّوَافُ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالمَرْوَةِ ‏ ‏وَرَمْيُ الْجِمَارِ لِإِقَامَةِ ذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23216,23216,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏عَنْ ‏ ‏بُدَيْلِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ { ‏فَرُوحٌ وَرَيْحَانٌ ‏} ‏بِرَفْعِ الرَّاءِ ‏","","",""],[23217,23217,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَهُوَ يُخَاصِمُ فِي أَرْضٍ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا ‏ ‏أَبَا سَلَمَةَ ‏ ‏اجْتَنِبْ الْأَرْضَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ظَلَمَ ‏ ‏قِيدَ ‏ ‏شِبْرٍ مِنْ الْأَرْضِ ‏ ‏طُوِّقَهُ ‏ ‏يَوْمَ الْقِيَامَةِ مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[23218,23218,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّهُ لَبَيْنَ ‏ ‏حَاقِنَتِي ‏ ‏وَذَاقِنَتِي ‏ ‏فَلَا أَكْرَهُ شِدَّةَ الْمَوْتِ لِأَحَدٍ أَبَدًا بَعْدَ مَا رَأَيْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23219,23219,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤْمِنَ ‏ ‏يُدْرِكُ ‏ ‏بِحُسْنِ خُلُقِهِ دَرَجَاتِ قَائِمِ اللَّيْلِ صَائِمِ النَّهَارِ ‏","","",""],[23220,23220,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَرْجِسَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَمُوتُ وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ فَيُدْخِلُ يَدَهُ فِي الْقَدَحِ ثُمَّ يَمْسَحُ وَجْهَهُ بِالْمَاءِ ثُمَّ يَقُولُ ‏ ‏اللَّهُمَّ أَعِنِّي عَلَى سَكَرَاتِ الْمَوْتِ ‏","","",""],[23221,23221,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُوتِرُ بِخَمْسِ سَجَدَاتٍ لَا يَجْلِسُ بَيْنَهُنَّ حَتَّى يَجْلِسَ فِي الْخَامِسَةِ ثُمَّ يُسَلِّمَ ‏","","",""],[23222,23222,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الطَّاعُونِ فَأَخْبَرَهَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ عَذَابًا يَبْعَثُهُ اللَّهُ عَزَّ وَجَلَّ عَلَى مَنْ يَشَاءُ فَجَعَلَهُ اللَّهُ عَزَّ وَجَلَّ رَحْمَةً لِلْمُؤْمِنِينَ فَلَيْسَ مِنْ عَبْدٍ يَقَعُ الطَّاعُونُ فِيهِ فَيَمْكُثُ فِي بَلَدِهِ صَابِرًا مُحْتَسِبًا يَعْلَمُ أَنَّهُ لَمْ يُصِبْهُ إِلَّا مَا كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ إِلَّا كَانَ لَهُ مِثْلُ أَجْرِ الشَّهِيدِ ‏","","",""],[23223,23223,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْمُونٍ الصَّائِغِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَهِيَ مُعْتَرِضَةٌ بَيْنَ يَدَيْهِ وَقَالَ أَلَيْسَ هُنَّ ‏ ‏أُمَّهَاتِكُمْ وَأَخَوَاتِكُمْ وَعَمَّاتِكُمْ ‏","","",""],[23224,23224,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ إِسْحَاقَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏اشْتَكَى ‏ ‏أَصْحَابُهُ ‏ ‏وَاشْتَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعَامِرُ بْنُ فُهَيْرَةَ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَبِلَالٌ ‏ ‏فَاسْتَأْذَنَتْ ‏ ‏عَائِشَةُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عِيَادَتِهِمْ فَأَذِنَ لَهَا فَقَالَتْ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏كَيْفَ تَجِدُكَ فَقَالَ ‏ ‏كُلُّ امْرِئٍ مُصَبَّحٌ فِي أَهْلِهِ ‏ ‏وَالْمَوْتُ ‏ ‏أَدْنَى ‏ ‏مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ ‏ ‏وَسَأَلَتْ ‏ ‏عَامِرًا ‏ ‏فَقَالَ ‏ ‏إِنِّي وَجَدْتُ الْمَوْتَ قَبْلَ ذَوْقِهِ ‏ ‏إِنَّ الْجَبَانَ ‏ ‏حَتْفُهُ ‏ ‏مِنْ فَوْقِهِ ‏ ‏وَسَأَلَتْ ‏ ‏بِلَالًا ‏ ‏فَقَالَ ‏ ‏يَا لَيْتَ شِعْرِي هَلْ أَبِيتَنَّ لَيْلَةً ‏ ‏بِفَجٍّ وَحَوْلِي إِذْخِرٌ ‏ ‏وَجَلِيلُ ‏ ‏فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَتْهُ بِقَوْلِهِمْ فَنَظَرَ إِلَى السَّمَاءِ وَقَالَ ‏ ‏اللَّهُمَّ حَبِّبْ إِلَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏كَمَا حَبَّبْتَ إِلَيْنَا ‏ ‏مَكَّةَ ‏ ‏وَأَشَدَّ اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏صَاعِهَا ‏ ‏وَفِي مُدِّهَا وَانْقُلْ وَبَاءَهَا إِلَى ‏ ‏مَهْيَعَةَ ‏ ‏وَهِيَ ‏ ‏الْجُحْفَةُ ‏ ‏كَمَا زَعَمُوا ‏","","",""],[23225,23225,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ أَبِي فَرْوَةَ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ مُسْلِمٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عُرْوَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَمْرَةَ بِنْتَ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَتْهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا زَنَتْ الْأَمَةُ فَاجْلِدُوهَا وَإِنْ زَنَتْ فَاجْلِدُوهَا وَإِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ بِيعُوهَا وَلَوْ ‏ ‏بِضَفِيرٍ ‏ ‏وَالضَّفِيرُ الْحَبْلُ ‏","","",""],[23226,23226,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُكَبِّرُ فِي الْعِيدَيْنِ سَبْعًا وَخَمْسًا قَبْلَ الْقِرَاءَةِ ‏","","",""],[23227,23227,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعُ بْنُ سُلَيْمَانَ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ أَبِي صَالِحٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ فَأَرْشَدَ اللَّهُ الْإِمَامَ وَعَفَا عَنْ الْمُؤَذِّنِ ‏","","",""],[23228,23228,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَعِيدِ بْنِ زَيْدِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏طَرَقَتْنِي الْحَيْضَةُ مِنْ اللَّيْلِ وَأَنَا إِلَى جَنْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَأَخَّرْتُ فَقَالَ مَا لَكِ ‏ ‏أَنُفِسْتِ ‏ ‏قَالَتْ لَا وَلَكِنِّي حِضْتُ قَالَ فَشُدِّي عَلَيْكِ ‏ ‏إِزَارَكِ ‏ ‏ثُمَّ عُودِي ‏","","",""],[23229,23229,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَهَرَ فِيهَا بِالْقِرَاءَةِ ‏ ‏يَعْنِي فِي الْكُسُوفِ ‏","","",""],[23230,23230,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اجْعَلُوا مِنْ صَلَاتِكُمْ فِي بُيُوتِكُمْ وَلَا تَجْعَلُوهَا عَلَيْكُمْ قُبُورًا ‏","","",""],[23231,23231,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏خَدِيجَةَ ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏وَرَقَةَ بْنِ نَوْفَلٍ ‏ ‏فَقَالَ ‏ ‏قَدْ رَأَيْتُهُ فِي الْمَنَامِ فَرَأَيْتُ عَلَيْهِ ثِيَابُ بَيَاضٍ فَأَحْسِبُهُ لَوْ كَانَ مِنْ أَهْلِ النَّارِ لَمْ يَكُنْ عَلَيْهِ ثِيَابَ بَيَاضٍ ‏","","",""],[23232,23232,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏بَكْرَ بْنَ سَوَادَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏يَزِيدَ بْنَ أَبِي يَزِيدَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا تَلَا هَذِهِ الْآيَةَ ‏ { ‏مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ ‏} ‏قَالَ إِنَّا ‏ ‏لَنُجْزَى بِكُلِّ عَمَلِنَا هَلَكْنَا إِذًا فَبَلَغَ ذَاكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ ‏ ‏يُجْزَى بِهِ الْمُؤْمِنُونَ فِي الدُّنْيَا فِي مُصِيبَةٍ فِي جَسَدِهِ فِيمَا ‏ ‏يُؤْذِيهِ ‏","","",""],[23233,23233,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَمُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏أَبَا النَّضْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ ‏ ‏مُسْتَجْمِعًا ‏ ‏ضَاحِكًا ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏ضَحِكًا ‏ ‏حَتَّى أَرَى مِنْهُ ‏ ‏لَهَوَاتِهِ ‏ ‏إِنَّمَا كَانَ يَتَبَسَّمُ وَقَالَتْ كَانَ إِذَا رَأَى غَيْمًا أَوْ رِيحًا عُرِفَ ذَلِكَ فِي وَجْهِهِ قَالَتْ يَا رَسُولَ اللَّهِ النَّاسُ إِذَا رَأَوْا الْغَيْمَ فَرِحُوا رَجَاءَ أَنْ يَكُونَ فِيهِ الْمَطَرُ وَأَرَاكَ إِذَا رَأَيْتَهُ عَرَفْتُ فِي وَجْهِكَ الْكَرَاهِيَةَ قَالَتْ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏مَا يُؤْمِنِّي أَنْ يَكُونَ فِيهِ عَذَابٌ قَدْ عُذِّبَ قَوْمٌ بِالرِّيحِ وَقَدْ رَأَى قَوْمٌ الْعَذَابَ فَقَالُوا ‏ { ‏هَذَا ‏ ‏عَارِضٌ ‏ ‏مُمْطِرُنَا ‏}","","",""],[23234,23234,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُيَيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْحُبُلِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏طَرَقَتْهَا الْحَيْضَةُ مِنْ اللَّيْلِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَأَشَارَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبٍ وَفِيهِ دَمٌ فَأَشَارَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الصَّلَاةِ اغْسِلِيهِ فَغَسَلَتْ مَوْضِعَ الدَّمِ ثُمَّ أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ الثَّوْبَ فَصَلَّى فِيهِ ‏","","",""],[23235,23235,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَحْرُمُ مِنْ الرَّضَاعَةِ مَا يَحْرُمُ مِنْ الْوِلَادَةِ ‏","","",""],[23236,23236,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ نَكَحَتْ بِغَيْرِ إِذْنِ وَلِيِّهَا فَنِكَاحُهَا بَاطِلٌ فَإِنْ أَصَابَهَا فَلَهَا مَهْرُهَا بِمَا أَصَابَ مِنْ فَرْجِهَا وَإِنْ اشْتَجَرُوا فَالسُّلْطَانُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ ‏","","",""],[23237,23237,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ الْكَافِرُ مِنْ كُفَّارِ ‏ ‏قُرَيْشٍ ‏ ‏يَمُوتُ ‏ ‏فَيَبْكِيهِ أَهْلُهُ فَيَقُولُونَ الْمُطْعِمُ الْجِفَانَ الْمُقَاتِلُ الَّذِي فَيَزِيدُهُ اللَّهُ عَذَابًا بِمَا يَقُولُونَ ‏","","",""],[23238,23238,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذُكِرَ رَجُلٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَيْرٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَلَمْ تَرَوْهُ يَتَعَلَّمُ الْقُرْآنَ ‏","","",""],[23239,23239,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ نَفْسِي خَبِيثَةٌ وَلَكِنْ يَقُولُ نَفْسِي لَقِسَةٌ ‏","","",""],[23240,23240,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ أَبِي الْوَلِيدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يُخْبِرُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا خَيْرَ فِي جَمَاعَةِ النِّسَاءِ إِلَّا فِي مَسْجِدٍ ‏ ‏أَوْ جِنَازَةٍ ‏","","",""],[23241,23241,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَقِيَ عَشْرٌ مِنْ رَمَضَانَ شَدَّ مِئْزَرَهُ وَاعْتَزَلَ أَهْلَهُ ‏","","",""],[23242,23242,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏صَاحِبِ الرُّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سُئِلَتْ عَنْ الْجَنَابَةِ قَالَتْ كُنْتُ ‏ ‏أَفْرُكُ الْجَنَابَةَ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23243,23243,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَدْرُونَ مَنْ السَّابِقُونَ إِلَى ظِلِّ اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ الَّذِينَ إِذَا أُعْطُوا الْحَقَّ قَبِلُوهُ وَإِذَا سُئِلُوهُ بَذَلُوهُ وَحَكَمُوا لِلنَّاسِ كَحُكْمِهِمْ لِأَنْفُسِهِمْ ‏","","",""],[23244,23244,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ عَبْدُ اللَّهِ بْنُ مُعَاوِيَةَ الزُّبَيْرِيُّ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏مَكَّةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ كَانَ ‏ ‏عُرْوَةُ ‏ ‏يَقُولُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّتَاهُ لَا أَعْجَبُ مِنْ فَهْمِكِ أَقُولُ زَوْجَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِنْتُ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَلَا أَعْجَبُ مِنْ عِلْمِكِ بِالشِّعْرِ وَأَيَّامِ النَّاسِ أَقُولُ ابْنَةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَكَانَ أَعْلَمَ النَّاسِ ‏ ‏أَوْ وَمِنْ أَعْلَمِ النَّاسِ ‏ ‏وَلَكِنْ أَعْجَبُ مِنْ عِلْمِكِ بِالطِّبِّ كَيْفَ هُوَ وَمِنْ أَيْنَ هُوَ قَالَ فَضَرَبَتْ عَلَى مَنْكِبِهِ وَقَالَتْ أَيْ ‏ ‏عُرَيَّةُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْقَمُ عِنْدَ آخِرِ عُمْرِهِ ‏ ‏أَوْ فِي آخِرِ عُمْرِهِ ‏ ‏فَكَانَتْ تَقْدَمُ عَلَيْهِ وُفُودُ ‏ ‏الْعَرَبِ ‏ ‏مِنْ كُلِّ وَجْهٍ فَتَنْعَتُ لَهُ ‏ ‏الْأَنْعَاتَ وَكُنْتُ أُعَالِجُهَا لَهُ فَمِنْ ثَمَّ ‏","","",""],[23245,23245,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ عَلَيْهِمْ السَّلَامُ يُصَلُّونَ عَلَى الَّذِينَ يَصِلُونَ الصُّفُوفَ ‏","","",""],[23246,23246,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏وَعَلَيَّ بَعْضُهُ ‏","","",""],[23247,23247,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏اسْتَأْذَنَّا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجِهَادِ فَقَالَ ‏ ‏جِهَادُكُنَّ ‏ ‏أَوْ حَسْبُكُنَّ ‏ ‏الْحَجُّ ‏","","",""],[23248,23248,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّها قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ كُلُّ أَهْلِكَ قَدْ دَخَلَ ‏ ‏الْبَيْتَ ‏ ‏غَيْرِي فَقَالَ أَرْسِلِي إِلَى ‏ ‏شَيْبَةَ ‏ ‏فَيَفْتَحَ لَكِ الْبَابَ فَأَرْسَلَتْ إِلَيْهِ فَقَالَ ‏ ‏شَيْبَةُ ‏ ‏مَا اسْتَطَعْنَا فَتْحَهُ فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ بِلَيْلٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلِّي فِي ‏ ‏الْحِجْرِ ‏ ‏فَإِنَّ قَوْمَكَ اسْتَقْصَرُوا عَنْ بِنَاءِ ‏ ‏الْبَيْتِ ‏ ‏حِينَ بَنَوْهُ ‏","","",""],[23249,23249,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ تُدْرِكُنِي الصَّلَاةُ وَأَنَا جُنُبٌ وَأَنَا أُرِيدُ الصِّيَامَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا تُدْرِكُنِي الصَّلَاةُ وَأَنَا جُنُبٌ وَأَنَا أُرِيدُ الصِّيَامَ فَأَغْتَسِلُ ثُمَّ أَصُومُ فَقَالَ الرَّجُلُ إِنَّا لَسْنَا مِثْلَكَ فَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ وَاللَّهِ ‏ ‏إِنِّي لَأَرْجُو أَنْ أَكُونَ ‏ ‏أَخْشَاكُمْ لِلَّهِ عَزَّ وَجَلَّ وَأَعْلَمَكُمْ بِمَا ‏ ‏أَتَّقِي ‏","","",""],[23250,23250,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْفُضَيْلِ بْنِ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيَارٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏اتَّبَعَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَتَّبِعُكَ لِأُصِيبَ مَعَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ قَالَ لَا قَالَ فَإِنَّا لَا نَسْتَعِينُ بِمُشْرِكٍ قَالَ فَقَالَ لَهُ فِي الْمَرَّةِ الثَّانِيَةِ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ قَالَ نَعَمْ فَانْطَلَقَ فَتَبِعَهُ ‏","","",""],[23251,23251,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمِيرَةَ ‏ ‏عَنْ ‏ ‏دُرَّةَ بِنْتِ أَبِي لَهَبٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ائْتُونِي بِوَضُوءٍ فَسَأَلْتُ ‏ ‏فَابْتَدَرْتُ ‏ ‏أَنَا ‏ ‏وَعَائِشَةُ ‏ ‏الْكُوزَ قَالَتْ فَبَدَرْتُهَا فَأَخَذْتُهُ أَنَا فَتَوَضَّأَ فَرَفَعَ ‏ ‏طَرْفَهُ ‏ ‏أَوْ عَيْنَهُ أَوْ بَصَرَهُ إِلَيَّ ‏ ‏فَقَالَ ‏ ‏أَنْتِ مِنِّي وَأَنَا مِنْكِ قَالَتْ فَأُتِيَ بِرَجُلٍ فَقَالَ مَا أَنَا فَعَلْتُهُ وَلَكِنْ قِيلَ لِي قَالَتْ وَكَانَ سَأَلَهُ عَلَى الْمِنْبَرِ مَنْ خَيْرُ النَّاسِ فَقَالَ أَفْقَهُهُمْ فِي دِينِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَأَوْصَلُهُمْ لِرَحِمِهِ ‏ ‏وَذَكَرَ فِيهِ ‏ ‏شَرِيكٌ ‏ ‏شَيْئَيْنِ آخَرَيْنِ لَمْ أَحْفَظْهُمَا ‏","","",""],[23252,23252,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي لُبَابَةَ الْعُقَيْلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يُفْطِرَ وَيُفْطِرُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يَصُومَ وَكَانَ يَقْرَأُ فِي كُلِّ لَيْلَةٍ ‏ ‏بِبَنِي إِسْرَائِيلَ ‏ ‏وَالزُّمَرِ ‏","","",""],[23253,23253,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَوَضَّأُ بَعْدَ الْغُسْلِ ‏","","",""],[23254,23254,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏لَمِيسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَخْلِطُ فِي الْعِشْرِينَ الْأُولَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَوْمٍ وَصَلَاةٍ فَإِذَا ‏ ‏دَخَلَتْ الْعَشْرُ ‏ ‏جَدَّ ‏ ‏وَشَدَّ الْمِئْزَرَ ‏","","",""],[23255,23255,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَعَلْنَاهُ مَرَّةً فَاغْتَسَلْنَا ‏ ‏يَعْنِي الَّذِي يُجَامِعُ وَلَا يُنْزِلُ ‏","","",""],[23256,23256,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي ‏","","",""],[23257,23257,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَلَيْكُنَّ ‏ ‏بِالْبَيْتِ ‏ ‏فَإِنَّهُ جِهَادُكُنَّ ‏","","",""],[23258,23258,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ فَمَنْ آتَيْنَاهُ مِنْهَا شَيْئًا بِطِيبِ نَفْسٍ مِنَّا وَطِيبِ طُعْمَةٍ وَلَا ‏ ‏إِشْرَاهٍ بُورِكَ لَهُ فِيهِ وَمَنْ آتَيْنَاهُ مِنْهَا شَيْئًا بِغَيْرِ طِيبِ نَفْسٍ مِنَّا وَغَيْرِ طِيبِ طُعْمَةٍ ‏ ‏وَإِشْرَاهٍ مِنْهُ لَمْ يُبَارَكْ لَهُ فِيهِ ‏","","",""],[23259,23259,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَبِرَتْ ‏ ‏سَوْدَةُ ‏ ‏وَهَبَتْ يَوْمَهَا لِي فَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ لِي بِيَوْمِهَا مَعَ نِسَائِهِ قَالَتْ وَكَانَتْ أَوَّلَ امْرَأَةٍ تَزَوَّجَهَا بَعْدَهَا ‏","","",""],[23260,23260,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ أَصْحَابُهُ يَعُودُونَهُ فَقَامُوا فَأَوْمَأَ إِلَيْهِمْ أَنْ اقْعُدُوا فَلَمَّا قَضَى صَلَاتَهُ قَالَ ‏ ‏الْإِمَامُ يُؤْتَمُّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا وَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا ‏","","",""],[23261,23261,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضَعُ رَأْسَهُ فِي حِجْرِي وَأَنَا حَائِضٌ فَيَقْرَأُ الْقُرْآنَ ‏","","",""],[23262,23262,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَنْ السَّابِقُونَ إِلَى ظِلِّ اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ قَالُوا اللَّهُ عَزَّ وَجَلَّ وَرَسُولُهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْلَمُ قَالَ الَّذِينَ إِذَا أُعْطُوا الْحَقَّ قَبِلُوهُ وَإِذَا سُئِلُوهُ بَذَلُوهُ وَحَكَمُوا لِلنَّاسِ حُكْمَهُمْ لِأَنْفُسِهِمْ ‏","","",""],[23263,23263,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَ ‏ ‏بِلَالٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَاتَتْ فُلَانَةُ وَاسْتَرَاحَتْ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏إِنَّمَا يَسْتَرِيحُ مَنْ دَخَلَ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏مَنْ غُفِرَ لَهُ ‏","","",""],[23264,23264,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا أَعْجَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْءٌ مِنْ الدُّنْيَا وَلَا أَعْجَبَهُ أَحَدٌ قَطُّ إِلَّا ذُو تُقًى ‏","","",""],[23265,23265,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏وَقَالَ ‏ ‏مُوسَى ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ عَنْهُ وَلِيُّهُ ‏","","",""],[23266,23266,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّهُ عَرَضَ هَذَا الْحَدِيثَ عَلَى ‏ ‏يَزِيدَ ‏ ‏فَعَرَفَهُ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا مَيِّتٍ مَاتَ وَعَلَيْهِ صِيَامٌ فَلْيَصُمْهُ عَنْهُ وَلِيُّهُ ‏","","",""],[23267,23267,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏وَالْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا أُعْجِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ وَلَا أَعْجَبَهُ شَيْءٌ مِنْ الدُّنْيَا إِلَّا أَنْ يَكُونَ فِيهَا ذُو تُقًى ‏","","",""],[23268,23268,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏مِنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏فَذَكَرَهُ عَنْ ‏ ‏أُمِّهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ ‏","","",""],[23269,23269,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَتْ امْرَأَةٌ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ أَيْ بِأَبِي وَأُمِّي إِنِّي ‏ ‏ابْتَعْتُ ‏ ‏أَنَا وَابْنِي مِنْ فُلَانٍ ثَمَرَ مَالِهِ فَأَحْصَيْنَاهُ وَحَشَدْنَاهُ لَا وَالَّذِي أَكْرَمَكَ بِمَا أَكْرَمَكَ بِهِ مَا أَصَبْنَا مِنْهُ شَيْئًا إِلَّا شَيْئًا نَأْكُلُهُ فِي بُطُونِنَا أَوْ نُطْعِمُهُ مِسْكِينًا رَجَاءَ الْبَرَكَةِ فَنَقَصْنَا عَلَيْهِ فَجِئْنَا نَسْتَوْضِعُهُ مَا نَقَصْنَاهُ فَحَلَفَ بِاللَّهِ لَا يَضَعُ لَنَا شَيْئًا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَأَلَّى لَا أَصْنَعُ خَيْرًا ثَلَاثَ مِرَارٍ قَالَ فَبَلَغَ ذَلِكَ صَاحِبَ التَّمْرِ فَجَاءَهُ فَقَالَ أَيْ بِأَبِي وَأُمِّي إِنْ شِئْتَ وَضَعْتُ مَا نَقَصُوا وَإِنْ شِئْتَ مِنْ رَأْسِ الْمَالِ مَا شِئْتَ فَوَضَعَ مَا نَقَصُوا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ ‏","","",""],[23270,23270,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏فَقَالَ ‏ ‏أَبِي ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ ‏ ‏وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَلَوْ رَأَى حَالَهُنَّ الْيَوْمَ مَنَعَهُنَّ ‏","","",""],[23271,23271,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا ثِمَارَكُمْ حَتَّى ‏ ‏يَبْدُوَ صَلَاحُهَا ‏ ‏وَتَنْجُوَ مِنْ ‏ ‏الْعَاهَةِ ‏","","",""],[23272,23272,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُرَيْمُ بْنُ سُفْيَانَ البَجَلِيُّ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتُقَبِّلُونَ الصِّبْيَانَ قَالَ وَاللَّهِ مَا نُقَبِّلُهُمْ قَالَ لَا أَمْلِكُ أَنْ كَانَ اللَّهُ عَزَّ وَجَلَّ نَزَعَ مِنْكَ الرَّحْمَةَ ‏","","",""],[23273,23273,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُكَبِّرُ فِي الْعِيدَيْنِ سَبْعًا فِي الرَّكْعَةِ الْأُولَى وَخَمْسًا فِي الْآخِرَةِ سِوَى تَكْبِيرَتَيْ الرُّكُوعِ ‏","","",""],[23274,23274,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سَلَمَةَ الْمَخْزُومِيِّ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ عَلَى كُلِّ أَحْيَانِهِ ‏","","",""],[23275,23275,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَنِي سُوَاءَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏قُلْتُ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَجْنَبَ فَغَسَلَ رَأْسَهُ بِغُسْلٍ اجْتَزَأَ بِذَلِكَ أَمْ يُفِيضُ الْمَاءَ عَلَى رَأْسِهِ قَالَتْ بَلْ كَانَ يُفِيضُ عَلَى رَأْسِهِ الْمَاءَ ‏","","",""],[23276,23276,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ التَّلَفُّتِ فِي الصَّلَاةِ فَقَالَ ‏ ‏اخْتِلَاسٌ ‏ ‏يَخْتَلِسُهُ ‏ ‏الشَّيْطَانُ مِنْ صَلَاةِ الْعَبْدِ ‏","","",""],[23277,23277,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ثَوْبٌ بَعْضُهُ عَلَيَّ ‏","","",""],[23278,23278,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ وَلَّاهُ اللَّهُ عَزَّ وَجَلَّ مِنْ أَمْرِ الْمُسْلِمِينَ شَيْئًا فَأَرَادَ بِهِ خَيْرًا جَعَلَ لَهُ وَزِيرَ صِدْقٍ فَإِنْ نَسِيَ ذَكَّرَهُ وَإِنْ ذَكَرَ أَعَانَهُ ‏","","",""],[23279,23279,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مُسْلِمِ بْنِ بَانَكَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏الْخُزَاعِيُّ ‏ ‏ابْنُ أَخِي ‏ ‏عَائِشَةَ ‏ ‏لِأُمِّهَا ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِيَّاكِ ‏ ‏وَمُحَقَّرَاتِ ‏ ‏الذُّنُوبِ فَإِنَّ لَهَا مِنْ اللَّهِ عَزَّ وَجَلَّ طَالِبًا ‏","","",""],[23280,23280,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَرْجِسَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَمُوتُ وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ وَهُوَ يُدْخِلُ يَدَهُ فَيَمْسَحُ بِهِ وَجْهَهُ وَيَقُولُ ‏ ‏اللَّهُمَّ أَعِنِّي عَلَى سَكَرَاتِ الْمَوْتِ ‏","","",""],[23281,23281,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَصْحَابَ هَذِهِ الصُّوَرِ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ يُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[23282,23282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ سَائِلًا سَأَلَ قَالَتْ فَأَمَرْتُ الْخَادِمَ فَأَخْرَجَ لَهُ شَيْئًا قَالَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهَا ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏لَا تُحْصِي ‏ ‏فَيُحْصِي اللَّهُ عَلَيْكِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏","","",""],[23283,23283,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دُوَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏زُرْعَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدُّنْيَا دَارُ مَنْ لَا دَارَ لَهُ وَمَالُ مَنْ لَا مَالَ لَهُ وَلَهَا يَجْمَعُ مَنْ لَا عَقْلَ لَهُ ‏","","",""],[23284,23284,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏يَمُرُّ بِنَا هِلَالٌ وَهِلَالٌ مَا يُوقَدُ فِي بَيْتٍ مِنْ بُيُوتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَارٌ قَالَ قُلْتُ يَا خَالَةُ فَعَلَى أَيِّ شَيْءٍ كُنْتُمْ تَعِيشُونَ قَالَتْ عَلَى ‏ ‏الْأَسْوَدَيْنِ ‏ ‏التَّمْرِ وَالْمَاءِ ‏","","",""],[23285,23285,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏دُوَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ رُومَانَ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏وَالَّذِي بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَقِّ ‏ ‏مَا رَأَى مُنْخُلًا وَلَا أَكَلَ خُبْزًا مَنْخُولًا مُنْذُ بَعَثَهُ اللَّهُ عَزَّ وَجَلَّ إِلَى أَنْ قُبِضَ قُلْتُ كَيْفَ تَأْكُلُونَ الشَّعِيرَ قَالَتْ كُنَّا نَقُولُ أُفٍّ ‏","","",""],[23286,23286,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ عَطَاءٍ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا نَخْرُجُ نُجَاهِدُ مَعَكُمْ قَالَ لَا ‏ ‏جِهَادُكُنَّ الْحَجُّ ‏ ‏الْمَبْرُورُ ‏ ‏وَهُوَ لَكُنَّ جِهَادٌ ‏","","",""],[23287,23287,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏وَأَحْسَنَ الثَّنَاءَ عَلَيْهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَسْكَرَ ‏ ‏الْفَرْقُ ‏ ‏مِنْهُ إِذَا شَرِبْتَهُ فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو تُمَيْلَةَ يَحْيَى بْنُ وَاضِحٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا عُثْمَانَ عَمْرَو بْنَ سُلَيْمٍ ‏ ‏يَقْضِي عَلَى بَابِهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهُوَ الَّذِي رَوَى عَنْهُ ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏وَرَوَى عَنْه ‏ ‏مُطَرِّفُ بْنُ طَرِيفٍ ‏ ‏وَرَبِيعُ بْنُ صَبِيحٍ ‏ ‏وَلَيْثُ بْنُ أَبِي سُلَيْمٍ ‏","","",""],[23288,23288,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَقَدْتُهُ مِنْ اللَّيْلِ فَإِذَا هُوَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَقَالَ ‏ ‏سَلَامٌ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَأَنْتُمْ لَنَا فَرَطٌ وَإِنَّا بِكُمْ لَاحِقُونَ اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ وَلَا تَفْتِنَّا بَعْدَهُمْ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23289,23289,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَفَعَتْهُ قَالَتْ قَالَ ‏ ‏صَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ غَيْرَ مُتَرَبِّعٍ ‏","","",""],[23290,23290,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِأَهْلِ بَيْتٍ خَيْرًا أَدْخَلَ عَلَيْهِمْ الرِّفْقَ ‏","","",""],[23291,23291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي أَنَّ ‏ ‏أُمَّ بَكْرٍ ‏ ‏أَخْبَرْتُهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْمَرْأَةِ الَّتِي ‏ ‏تَرَى مَا ‏ ‏يُرِيبُهَا ‏ ‏بَعْدَ الطُّهْرِ إِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏أَوْ قَالَ عُرُوقٌ ‏","","",""],[23292,23292,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَغْتَسِلُ ثُمَّ ‏ ‏يَغْدُو ‏ ‏إِلَى الصَّلَاةِ فَأَسْمَعُ قِرَاءَتَهُ وَيَصُومُ ‏","","",""],[23293,23293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ حَفْصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يَقُولُ ‏ ‏دَخَلْتُ أَنَا وَأَخُو ‏ ‏عَائِشَةَ ‏ ‏مِنْ الرَّضَاعَةِ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَهَا ‏ ‏أَخُوهَا عَنْ غُسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَتْ بِإِنَاءٍ نَحْوًا مِنْ ‏ ‏صَاعٍ ‏ ‏فَاغْتَسَلَتْ وَأَفْرَغَتْ عَلَى رَأْسِهَا ثَلَاثًا وَبَيْنَنَا وَبَيْنَهَا الْحِجَابُ ‏","","",""],[23294,23294,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ صُخَيْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرِّمُوا مِنْ الرَّضَاعَةِ مَا تُحَرِّمُوا مِنْ الْوِلَادَةِ ‏","","",""],[23295,23295,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُثْمَانَ الْأَنْصَارِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَسْكَرَ مِنْهُ ‏ ‏الْفَرْقُ ‏ ‏فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ ‏","","",""],[23296,23296,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏آمِنَةَ الْقَيْسِيَّةِ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَشْرَبُوا إِلَّا فِيمَا ‏ ‏أُوكِئَ عَلَيْهِ ‏","","",""],[23297,23297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَعَنَتْ بَعِيرًا لَهَا فَأَمَرَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُرَدَّ وَقَالَ ‏ ‏لَا يَصْحَبُنِي شَيْءٌ مَلْعُونٌ ‏","","",""],[23298,23298,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏وَالْأَشْيَبُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَضَعُ رَأْسَهُ فِي حِجْرِهَا وَهِيَ حَائِضٌ فَيَقْرَأُ الْقُرْآنَ ‏","","",""],[23299,23299,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ ‏ ‏يُبَاشِرُ ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ لَهُ مَا فَوْقَ ‏ ‏الْإِزَارِ ‏","","",""],[23300,23300,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضَعَ ‏ ‏لِحَسَّانَ ‏ ‏مِنْبَرًا فِي الْمَسْجِدِ ‏ ‏يُنَافِحُ ‏ ‏عَنْهُ بِالشِّعْرِ ثُمَّ يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيُؤَيِّدُ ‏ ‏حَسَّانَ ‏ ‏بِرُوحِ الْقُدُسِ ‏ ‏يُنَافِحُ ‏ ‏عَنْ رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏","","",""],[23301,23301,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ يَعْنِي ابْنَ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَدَّانُ فَقِيلَ لَهَا مَا لَكِ وَلِلدَّيْنِ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ كَانَتْ لَهُ نِيَّةٌ فِي أَدَاءِ دَيْنِهِ إِلَّا كَانَ لَهُ مِنْ اللَّهِ عَزَّ وَجَلَّ عَوْنٌ فَأَنَا أَلْتَمِسُ ذَلِكَ الْعَوْنَ ‏","","",""],[23302,23302,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ مِنْ الدُّنْيَا ثَلَاثَةٌ الطَّعَامُ وَالنِّسَاءُ وَالطِّيبُ فَأَصَابَ ثِنْتَيْنِ وَلَمْ يُصِبْ وَاحِدَةً أَصَابَ النِّسَاءَ وَالطِّيبَ وَلَمْ يُصِبْ الطَّعَامَ ‏","","",""],[23303,23303,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ امْرِئٍ تَكُونُ لَهُ صَلَاةٌ بِاللَّيْلِ فَيَغْلِبُهُ عَلَيْهَا نَوْمٌ إِلَّا كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ أَجْرَ صَلَاتِهِ وَكَانَ نَوْمُهُ ذَلِكَ صَدَقَةً ‏","","",""],[23304,23304,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَ صَوْتَ صَبِيٍّ يَبْكِي فَقَالَ ‏ ‏مَا لِصَبِيِّكُمْ هَذَا يَبْكِي فَهَلَّا ‏ ‏اسْتَرْقَيْتُمْ ‏ ‏لَهُ مِنْ ‏ ‏الْعَيْنِ ‏","","",""],[23305,23305,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ هِنْدٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ السَّبْعَ الْأُوَلَ فَهُوَ ‏ ‏حَبْرٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَهَذَا أَرَى أَنَّ فِيهِ عَنْ أَبِيهِ عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏وَلَكِنْ كَذَا كَانَ فِي الْكِتَابِ فَلَا أَدْرِي أَغْفَلَهُ أَبِي أَوْ كَذَا هُوَ مُرْسَلٌ ‏","","",""],[23306,23306,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَحَرَّوْا ‏ ‏لَيْلَةَ الْقَدْرِ فِي الْوَتْرِ مِنْ الْعَشْرِ ‏","","",""],[23307,23307,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَمَضَانَ فَقَالَتْ مَا كَانَ يَزِيدُ فِي رَمَضَانَ وَلَا فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً ‏ ‏يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ طُولِهِنَّ وَحُسْنِهِنَّ ثُمَّ ‏ ‏يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ ثُمَّ ‏ ‏يُصَلِّي ثَلَاثًا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَتَنَامُ قَبْلَ أَنْ تُوتِرَ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ عَيْنِي تَنَامُ وَلَا يَنَامُ قَلْبِي ‏","","",""],[23308,23308,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ يُنْتَفَعَ بِجُلُودِ الْمَيْتَةِ إِذَا ‏ ‏دُبِغَتْ ‏","","",""],[23309,23309,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏أَمَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنْ أَكْتُبَ لَهَا مُصْحَفًا قَالَتْ إِذَا بَلَغْتَ إِلَى هَذِهِ الْآيَةِ ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ‏} ‏فَآذِنِّي فَلَمَّا بَلَغْتُهَا ‏ ‏آذَنْتُهَا ‏ ‏فَأَمْلَتْ عَلَيَّ ‏ ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَصَلَاةِ الْعَصْرِ وَقُومُوا لِلَّهِ ‏ ‏قَانِتِينَ ‏ ‏قَالَتْ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23310,23310,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَزْرَةَ الْقَاصُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُصَلِّيَنَّ أَحَدُكُمْ بِحَضْرَةِ الطَّعَامِ وَلَا وَهُوَ يُدَافِعُهُ ‏ ‏الْأَخْبَثَانِ ‏","","",""],[23311,23311,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الزُّهْرِيُّ ‏ ‏مِنْ آلِ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَنَعَ أَمْرًا مِنْ غَيْرِ أَمْرِنَا فَهُوَ مَرْدُودٌ ‏","","",""],[23312,23312,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ فِرَاشُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدَمًا ‏ ‏وَحَشْوُهُ لِيفٌ ‏","","",""],[23313,23313,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏شَبِعْنَا ‏ ‏مِنْ ‏ ‏الْأَسْوَدَيْنِ ‏ ‏الْمَاءِ وَالتَّمْرِ ‏","","",""],[23314,23314,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ الْحَضْرَمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ مِنْ أَوَّلِ اللَّيْلِ أَوْ مِنْ آخِرِهِ فَقَالَتْ كُلُّ ذَلِكَ كَانَ يَفْعَلُ ‏ ‏رُبَّمَا أَوْتَرَ أَوَّلَ اللَّيْلِ وَرُبَّمَا أَوْتَرَ آخِرَهُ قُلْتُ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً قُلْتُ كَيْفَ كَانَتْ قِرَاءَتُهُ يُسِرُّ أَوْ يَجْهَرُ قَالَتْ كُلُّ ذَلِكَ كَانَ يَفْعَلُ رُبَّمَا أَسَرَّ وَرُبَّمَا جَهَرَ قَالَ قُلْتُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً قَالَ قُلْتُ كَيْفَ كَانَ يَصْنَعُ فِي الْجَنَابَةِ أَكَانَ يَغْتَسِلُ قَبْلَ أَنْ يَنَامَ أَوْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ قَالَتْ كُلُّ ذَلِكَ كَانَ يَفْعَلُ رُبَّمَا اغْتَسَلَ فَنَامَ وَرُبَّمَا تَوَضَّأَ وَنَامَ قَالَ قُلْتُ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً ‏","","",""],[23315,23315,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ نَبِيٍّ إِلَّا تُقْبَضُ نَفْسُهُ ثُمَّ يَرَى الثَّوَابَ ثُمَّ تُرَدُّ إِلَيْهِ فَيُخَيَّرُ بَيْنَ أَنْ تُرَدَّ إِلَيْهِ إِلَى أَنْ يَلْحَقَ فَكُنْتُ قَدْ حَفِظْتُ ذَلِكَ مِنْهُ فَإِنِّي لَمُسْنِدَتُهُ إِلَى صَدْرِي فَنَظَرْتُ إِلَيْهِ حَتَّى مَالَتْ عُنُقُهُ فَقُلْتُ قَدْ ‏ ‏قَضَى ‏ ‏قَالَتْ فَعَرَفْتُ الَّذِي قَالَ فَنَظَرْتُ إِلَيْهِ حَتَّى ارْتَفَعَ فَنَظَرَ قَالَتْ قُلْتُ إِذَنْ وَاللَّهِ لَا يَخْتَارُنَا فَقَالَ مَعَ الرَّفِيقِ الْأَعْلَى فِي الْجَنَّةِ ‏ { ‏مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنْ النَّبِيِّينَ وَالصِّدِّيقِينَ ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[23316,23316,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حُمِّلَ مِنْ أُمَّتِي دَيْنًا ثُمَّ جَهِدَ فِي قَضَائِهِ فَمَاتَ وَلَمْ يَقْضِهِ فَأَنَا وَلِيُّهُ ‏","","",""],[23317,23317,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي مِنْ الضُّحَى أَرْبَعَ رَكَعَاتٍ ‏","","",""],[23318,23318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ أَوَّلَ مَنْ يَهْلِكُ مِنْ النَّاسِ قَوْمُكِ قَالَتْ قُلْتُ جَعَلَنِي اللَّهُ فِدَاءَكَ ‏ ‏أَبَنِي تَيْمٍ ‏ ‏قَالَ لَا وَلَكِنْ هَذَا الْحَيُّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏تَسْتَحْلِيهِمْ ‏ ‏الْمَنَايَا ‏ ‏وَتَنَفَّسُ عَنْهُمْ أَوَّلَ النَّاسِ هَلَاكًا قُلْتُ فَمَا بَقَاءُ النَّاسِ بَعْدَهُمْ قَالَ هُمْ صُلْبُ النَّاسِ فَإِذَا هَلَكُوا هَلَكَ النَّاسُ ‏","","",""],[23319,23319,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ ‏ ‏أُمَّ كُلْثُومٍ ‏ ‏أَخْبَرَتْهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّهَا وَالنَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَا ذَلِكَ ثُمَّ اغْتَسَلَا مِنْهُ يَوْمًا ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أُمَّ كُلْثُومٍ ‏ ‏أَخْبَرَتْهُ أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[23320,23320,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ مِنْ حِينِ تَطْلُعُ الشَّمْسُ حَتَّى تَرْتَفِعَ وَمَنْ حِينِ تَصُوبُ حَتَّى تَغِيبَ ‏","","",""],[23321,23321,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مَا بَيْنَ صَلَاةِ الْعِشَاءِ الْآخِرَةِ إِلَى الْفَجْرِ إِحْدَى عَشْرَةَ رَكْعَةً يُسَلِّمُ فِي كُلِّ اثْنَيْنِ وَيُوتِرُ بِوَاحِدَةٍ وَيَسْجُدُ فِي سُبْحَتِهِ بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ بِخَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ فَإِذَا سَكَتَ الْمُؤَذِّنُ بِالْأُولَى مِنْ أَذَانِهِ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيَخْرُجَ مَعَهُ ‏","","",""],[23322,23322,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَدَيْهِ عَلَى مَعْرَفَةِ فَرَسٍ وَهُوَ يُكَلِّمُ رَجُلًا قُلْتُ رَأَيْتُكَ وَاضِعًا يَدَيْكَ عَلَى مَعْرَفَةِ فَرَسِ ‏ ‏دِحْيَةَ الْكَلْبِيِّ ‏ ‏وَأَنْتَ تُكَلِّمُهُ قَالَ وَرَأَيْتِ قَالَتْ نَعَمْ قَالَ ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يُقْرِئُكِ السَّلَامَ قَالَتْ وَعَلَيْهِ السَّلَامُ ‏ ‏وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ جَزَاهُ اللَّهُ خَيْرًا مِنْ صَاحِبٍ ‏ ‏وَدَخِيلٍ ‏ ‏فَنِعْمَ الصَّاحِبُ وَنِعْمَ الدَّخِيلُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الدَّخِيلُ ‏ ‏الضَّيْفُ ‏","","",""],[23323,23323,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ مِهْرَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حِطَّانَ السَّدُوسِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ أَعَلَى النِّسَاءِ جِهَادٌ قَالَ ‏ ‏الْحَجُّ وَالْعُمْرَةُ هُوَ جِهَادُ النِّسَاءِ ‏","","",""],[23324,23324,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْعَلَاءِ الشَّنِّيُّ ‏ ‏مَنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحُ بْنُ سَرْجٍ ‏ ‏حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ حِطَّانَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَاكَرْتُهَا حَتَّى ذَكَرْنَا الْقَاضِيَ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَأْتِيَنَّ عَلَى الْقَاضِي الْعَدْلِ يَوْمَ الْقِيَامَةِ سَاعَةٌ ‏ ‏يَتَمَنَّى أَنَّهُ لَمْ يَقْضِ بَيْنَ اثْنَيْنِ فِي تَمْرَةٍ قَطُّ ‏","","",""],[23325,23325,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَقُولُ لِرَجُلٍ مَا اسْمُكَ فَقَالَ ‏ ‏شِهَابٌ ‏ ‏فَقَالَ أَنْتَ ‏ ‏هِشَامٌ ‏","","",""],[23326,23326,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فَرَجُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْوَلِيدِ الزُّبَيْدِيِّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏لَوْ كَانَ عِنْدَنَا مَنْ يُحَدِّثُنَا قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَلَا أَبْعَثُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَسَكَتَ ثُمَّ قَالَ لَوْ كَانَ عِنْدَنَا مَنْ يُحَدِّثُنَا فَقُلْتُ أَلَا أَبْعَثُ إِلَى ‏ ‏عُمَرَ ‏ ‏فَسَكَتَ قَالَتْ ثُمَّ دَعَا وَصِيفًا بَيْنَ يَدَيْهِ فَسَارَّهُ فَذَهَبَ قَالَتْ فَإِذَا ‏ ‏عُثْمَانُ ‏ ‏يَسْتَأْذِنُ فَأَذِنَ لَهُ فَدَخَلَ فَنَاجَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَوِيلًا ثُمَّ قَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ مُقَمِّصُكَ قَمِيصًا فَإِنْ أَرَادَكَ الْمُنَافِقُونَ عَلَى أَنْ تَخْلَعَهُ فَلَا تَخْلَعْهُ لَهُمْ وَلَا كَرَامَةَ يَقُولُهَا لَهُ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[23327,23327,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَضْرَمِيُّ بْنُ لَاحِقٍ ‏ ‏أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏قَالَتْ دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَبْكِي فَقَالَ لِي مَا يُبْكِيكِ قُلْتُ يَا رَسُولَ اللَّهِ ذَكَرْتُ ‏ ‏الدَّجَّالَ ‏ ‏فَبَكَيْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ يَخْرُجْ ‏ ‏الدَّجَّالُ ‏ ‏وَأَنَا حَيٌّ كَفَيْتُكُمُوهُ وَإِنْ يَخْرُجْ ‏ ‏الدَّجَّالُ ‏ ‏بَعْدِي فَإِنَّ رَبَّكُمْ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ وَإِنَّهُ يَخْرُجُ فِي يَهُودِيَّةِ ‏ ‏أَصْبَهَانَ ‏ ‏حَتَّى يَأْتِيَ ‏ ‏الْمَدِينَةَ ‏ ‏فَيَنْزِلَ نَاحِيَتَهَا وَلَهَا يَوْمَئِذٍ سَبْعَةُ أَبْوَابٍ عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكَانِ فَيَخْرُجَ إِلَيْهِ شِرَارُ أَهْلِهَا حَتَّى ‏ ‏الشَّامِ ‏ ‏مَدِينَةٍ ‏ ‏بِفِلَسْطِينَ ‏ ‏بِبَابِ ‏ ‏لُدٍّ ‏ ‏وَقَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏مَرَّةً حَتَّى يَأْتِيَ ‏ ‏فِلَسْطِينَ ‏ ‏بَابَ لُدٍّ ‏ ‏فَيَنْزِلَ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَيَقْتُلَهُ ثُمَّ يَمْكُثَ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فِي الْأَرْضِ أَرْبَعِينَ سَنَةً إِمَامًا عَدْلًا وَحَكَمًا مُقْسِطًا ‏","","",""],[23328,23328,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا جُعِلَ الطَّوَافُ ‏ ‏بِالْكَعْبَةِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَرَمْيُ الْجِمَارِ لِإِقَامَةِ ذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23329,23329,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏يَزِيدَ أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏ذُيُولِ ‏ ‏النِّسَاءِ قَالَ شِبْرٌ قَالَتْ قُلْتُ إِذَنْ تَخْرُجَ سُوقُهُنَّ قَالَ فَذِرَاعٌ ‏","","",""],[23330,23330,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ جَهْدًا يَكُونُ بَيْنَ يَدَيْ ‏ ‏الدَّجَّالِ ‏ ‏فَقَالُوا ‏ ‏أَيُّ الْمَالِ خَيْرٌ يَوْمَئِذٍ قَالَ غُلَامٌ شَدِيدٌ يَسْقِي أَهْلَهُ الْمَاءَ وَأَمَّا الطَّعَامُ فَلَيْسَ قَالُوا فَمَا طَعَامُ الْمُؤْمِنِينَ يَوْمَئِذٍ قَالَ التَّسْبِيحُ وَالتَّقْدِيسُ وَالتَّحْمِيدُ وَالتَّهْلِيلُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَأَيْنَ ‏ ‏الْعَرَبُ ‏ ‏يَوْمَئِذٍ قَالَ ‏ ‏الْعَرَبُ ‏ ‏يَوْمَئِذٍ قَلِيلٌ ‏","","",""],[23331,23331,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَعْنَى عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي نَفَرٍ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فَجَاءَ بَعِيرٌ فَسَجَدَ لَهُ فَقَالَ أَصْحَابُهُ يَا رَسُولَ اللَّهِ تَسْجُدُ لَكَ الْبَهَائِمُ وَالشَّجَرُ فَنَحْنُ أَحَقُّ أَنْ نَسْجُدَ لَكَ فَقَالَ ‏ ‏اعْبُدُوا رَبَّكُمْ وَأَكْرِمُوا أَخَاكُمْ وَلَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا وَلَوْ أَمَرَهَا أَنْ تَنْقُلَ مِنْ جَبَلٍ أَصْفَرَ إِلَى جَبَلٍ أَسْوَدَ وَمِنْ جَبَلٍ أَسْوَدَ إِلَى جَبَلٍ أَبْيَضَ كَانَ يَنْبَغِي لَهَا أَنْ تَفْعَلَهُ ‏","","",""],[23332,23332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقُومُ فِي صَلَاةِ ‏ ‏الْإِنَابَةِ ‏ ‏فَيَرْكَعُ ثَلَاثَ رَكَعَاتٍ ثُمَّ يَسْجُدُ ثُمَّ يَرْكَعُ ثَلَاثَ رَكَعَاتٍ ثُمَّ يَسْجُدُ ‏","","",""],[23333,23333,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَسَفَتْ الشَّمْسُ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُصَلَّى فَكَبَّرَ وَكَبَّرَ النَّاسُ ثُمَّ قَرَأَ فَجَهَرَ بِالْقِرَاءَةِ وَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ قَامَ فَقَرَأَ فَأَطَالَ الْقِرَاءَةَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ رَأْسَهُ ثُمَّ سَجَدَ ثُمَّ قَامَ فَفَعَلَ فِي الثَّانِيَةِ مِثْلَ ذَلِكَ ثُمَّ قَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا فَعَلُوا ذَلِكَ ‏ ‏فَافْزَعُوا ‏ ‏إِلَى الصَّلَاةِ ‏","","",""],[23334,23334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ هَوْذَةَ الْقُرَيْعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أُمَّ هِلَالٍ ‏ ‏حَدَّثَتْهُ أَنَّهَا سَمِعَتْ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى غَيْمًا إِلَّا رَأَيْتُ فِي وَجْهِهِ الْهَيْجَ فَإِذَا مَطَرَتْ سَكَنَ ‏","","",""],[23335,23335,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَظَنَنْتُ أَنَّهُ يَأْتِي بَعْضَ نِسَائِهِ فَاتَّبَعْتُهُ فَأَتَى الْمَقَابِرَ ثُمَّ قَالَ ‏ ‏سَلَامٌ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا بِكُمْ لَاحِقُونَ اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ وَلَا تَفْتِنَّا بَعْدَهُمْ قَالَتْ ثُمَّ الْتَفَتَ فَرَآنِي فَقَالَ وَيْحَهَا لَوْ اسْتَطَاعَتْ مَا فَعَلَتْ ‏ ‏قَالَ ‏ ‏ذَكَرَهُ ‏ ‏شَرِيكٌ ‏ ‏مَرَّةً أُخْرَى ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[23336,23336,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَأْذِنُ إِذَا كَانَ يَوْمُ الْمَرْأَةِ مِنَّا بَعْدَ أَنْ نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ ‏ ‏وَتُؤْوِي ‏ ‏إِلَيْكَ مَنْ تَشَاءُ وَمَنْ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا ‏ ‏جُنَاحَ ‏ ‏عَلَيْكَ ‏} ‏قَالَتْ فَقُلْتُ لَهَا مَا كُنْتِ تَقُولِينَ لَهُ قَالَتْ كُنْتُ أَقُولُ لَهُ إِنْ كَانَ ذَلِكَ إِلَيَّ فَإِنِّي لَا أُرِيدُ يَا رَسُولَ اللَّهِ أَنْ ‏ ‏أُوثِرَ ‏ ‏عَلَيْكَ أَحَدًا ‏","","",""],[23337,23337,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏سَوْدَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ قَدْ وَهَبْتُ يَوْمِي ‏ ‏لِعَائِشَةَ ‏ ‏فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ لَهَا يَوْمَهَا ‏","","",""],[23338,23338,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏يُمْنِ ‏ ‏الْمَرْأَةِ تَيْسِيرَ خِطْبَتِهَا وَتَيْسِيرَ ‏ ‏صَدَاقِهَا ‏ ‏وَتَيْسِيرَ رَحِمِهَا ‏","","",""],[23339,23339,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَرْجِسٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَكَلَ بِشِمَالِهِ أَكَلَ مَعَهُ الشَّيْطَانُ وَمَنْ شَرِبَ بِشِمَالِهِ شَرِبَ مَعَهُ الشَّيْطَانُ ‏","","",""],[23340,23340,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَامِرٍ ‏ ‏بَعَثَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏بِنَفَقَةٍ وَكِسْوَةٍ فَقَالَتْ لِلرَّسُولِ إِنِّي يَا بُنَيَّ لَا أَقْبَلُ مِنْ أَحَدٍ شَيْئًا فَلَمَّا خَرَجَ قَالَتْ رُدُّوهُ عَلَيَّ فَرَدُّوهُ فَقَالَتْ إِنِّي ذَكَرْتُ شَيْئًا قَالَهُ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏مَنْ أَعْطَاكِ عَطَاءً بِغَيْرِ مَسْأَلَةٍ فَاقْبَلِيهِ فَإِنَّمَا هُوَ رِزْقٌ عَرَضَهُ اللَّهُ لَكِ ‏","","",""],[23341,23341,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَرْجِسٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَمُوتُ وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ وَهُوَ يُدْخِلُ يَدَهُ فِيهِ فَيَمْسَحُ بِهِ وَجْهَهُ وَيَقُولُ ‏ ‏اللَّهُمَّ أَعِنِّي عَلَى سَكَرَاتِ الْمَوْتِ ‏","","",""],[23342,23342,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قُبِضَ أَوْ ‏ ‏مَاتَ وَهُوَ بَيْنَ ‏ ‏حَاقِنَتِي ‏ ‏وَذَاقِنَتِي ‏ ‏فَلَا أَكْرَهُ شِدَّةَ الْمَوْتِ لِأَحَدٍ أَبَدًا بَعْدَ الَّذِي رَأَيْتُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23343,23343,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا ‏ ‏فَاطِمَةَ ‏ ‏ابْنَتَهُ فَسَارَّهَا فَبَكَتْ ثُمَّ سَارَّهَا فَضَحِكَتْ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ ‏ ‏لِفَاطِمَةَ ‏ ‏مَا هَذَا الَّذِي سَارَّكِ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَكَيْتِ ثُمَّ سَارَّكِ فَضَحِكْتِ قَالَتْ سَارَّنِي فَأَخْبَرَنِي بِمَوْتِهِ فَبَكَيْتُ ثُمَّ سَارَّنِي فَأَخْبَرَنِي أَنِّي أَوَّلُ مَنْ أَتْبَعُهُ مِنْ أَهْلِهِ فَضَحِكْتُ ‏","","",""],[23344,23344,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي تَمْرِ ‏ ‏الْعَالِيَةِ ‏ ‏شِفَاءً ‏ ‏أَوْ قَالَ ‏ ‏تِرْيَاقًا ‏ ‏أَوَّلَ بُكْرَةٍ عَلَى الرِّيقِ ‏","","",""],[23345,23345,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَخْرُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ لَهُنَّ ‏ ‏إِنَّ أَمْرَكُنَّ لَمِمَّا يُهِمُّنِي بَعْدِي وَلَنْ ‏ ‏يَصْبِرَ ‏ ‏عَلَيْكُنَّ إِلَّا الصَّابِرُونَ ‏ ‏و قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏صَخْرُ بْنُ عَبْدِ اللَّهِ ‏","","",""],[23346,23346,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ سُلَيْمَانَ الْحَضْرَمِيُّ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا جَلَسَ مَجْلِسًا أَوْ صَلَّى تَكَلَّمَ بِكَلِمَاتٍ فَسَأَلَتْهُ ‏ ‏عَائِشَةُ ‏ ‏عَنْ الْكَلِمَاتِ فَقَالَ ‏ ‏إِنْ تَكَلَّمَ بِخَيْرٍ كَانَ ‏ ‏طَابِعًا ‏ ‏عَلَيْهِنَّ إِلَى يَوْمِ الْقِيَامَةِ وَإِنْ تَكَلَّمَ بِغَيْرِ ذَلِكَ كَانَ كَفَّارَةً سُبْحَانَكَ وَبِحَمْدِكَ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ ‏","","",""],[23347,23347,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏آيَةُ الْخِيَارِ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنِّي أُرِيدُ أَنْ أَذْكُرَ لَكِ أَمْرًا فَلَا تَقْضِينَ فِيهِ شَيْئًا دُونَ أَبَوَيْكِ فَقَالَتْ وَمَا هُوَ قَالَتْ ‏ ‏فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَ عَلَيَّ هَذِهِ الْآيَةَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ ‏} { ‏إِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ ‏} ‏الْآيَةَ ‏ ‏كُلَّهَا قَالَتْ فَقُلْتُ قَدْ اخْتَرْتُ اللَّهَ عَزَّ وَجَلَّ وَرَسُولَهُ قَالَتْ فَفَرِحَ بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23348,23348,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَنَامُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فِرَاشٍ وَأَنَا حَائِضٌ وَعَلَيَّ ثَوْبٌ ‏","","",""],[23349,23349,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَ سَجْدَةً مِنْ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ وَمِنْ الْفَجْرِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا ‏","","",""],[23350,23350,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يُحْرِمَ غَسَلَ ‏ ‏بِخِطْمِيٍّ ‏ ‏وَأَشْنَانٍ وَدَهَنَهُ بِشَيْءٍ مِنْ زَيْتٍ غَيْرِ كَثِيرٍ قَالَتْ وَحَجَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّةً فَأَعْمَرَ نِسَاءَهُ وَتَرَكَنِي فَوَجَدْتُ فِي نَفْسِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْمَرَ نِسَاءَهُ وَتَرَكَنِي فَقُلْتُ يَا رَسُولَ اللَّهِ أَعْمَرْتَ نِسَاءَكَ وَتَرَكْتَنِي فَقَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏اخْرُجْ بِأُخْتِكَ فَلْتَعْتَمِرْ فَطُفْ بِهَا ‏ ‏الْبَيْتَ ‏ ‏وَالصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏ثُمَّ لِتَقْضِ ثُمَّ ائْتِنِي بِهَا قَبْلَ أَنْ أَبْرَحَ لَيْلَةَ ‏ ‏الْحَصْبَةِ ‏ ‏قَالَتْ فَإِنَّمَا أَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَصْبَةِ ‏ ‏مِنْ أَجْلِي ‏","","",""],[23351,23351,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ وَقَالَ ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِكَبْشٍ ‏ ‏أَقْرَنَ ‏ ‏يَطَأُ ‏ ‏فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ ثُمَّ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏هَلُمِّي ‏ ‏الْمُدْيَةَ ‏ ‏ثُمَّ قَالَ اسْتَحِدِّيهَا بِحَجَرٍ فَفَعَلَتْ ثُمَّ أَخَذَهَا وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ ثُمَّ ذَبَحَهُ وَقَالَ بِسْمِ اللَّهِ اللَّهُمَّ تَقَبَّلْ مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏وَآلِ ‏ ‏مُحَمَّدٍ ‏ ‏وَمِنْ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏ثُمَّ ضَحَّى بِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23352,23352,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَفْلَحُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَتَلْتُ ‏ ‏قَلَائِدَ ‏ ‏بُدْنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏قَلَّدَهَا ‏ ‏وَأَشْعَرَهَا ‏ ‏ثُمَّ وَجَّهَهَا إِلَى ‏ ‏الْبَيْتِ ‏ ‏وَأَقَامَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَمَا حَرُمَ عَلَيْهِ شَيْءٌ كَانَ لَهُ حِلًّا ‏","","",""],[23353,23353,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَدْلَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْبَطْحَاءِ ‏ ‏لَيْلَةَ النَّفْرِ إِدْلَاجًا ‏","","",""],[23354,23354,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يُزَوِّجَ شَيْئًا مِنْ بَنَاتِهِ جَلَسَ إِلَى ‏ ‏خِدْرِهَا ‏ ‏فَقَالَ إِنَّ فُلَانًا يَذْكُرُ فُلَانَةً يُسَمِّيهَا وَيُسَمِّي الرَّجُلَ الَّذِي يَذْكُرُهَا فَإِنْ هِيَ سَكَتَتْ زَوَّجَهَا وَإِنْ كَرِهَتْ نَقَرَتْ السِّتْرَ فَإِذَا نَقَرَتْهُ لَمْ يُزَوِّجْهَا ‏","","",""],[23355,23355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُحَمَّدٍ التَّيْمِيُّ وَهُوَ الْعَيْشِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنَّهُمْ لَيَبْكُونَ عَلَيْهِ وَإِنَّهُ لَيُعَذَّبُ فِي قَبْرِهِ بِذَنْبِهِ ‏","","",""],[23356,23356,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏عَطَسَ رَجُلٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا أَقُولُ يَا رَسُولَ اللَّهِ قَالَ قُلْ الْحَمْدُ لِلَّهِ قَالَ الْقَوْمُ مَا نَقُولُ لَهُ يَا رَسُولَ اللَّهِ قَالَ قُولُوا لَهُ يَرْحَمُكَ اللَّهُ قَالَ مَا أَقُولُ لَهُمْ يَا رَسُولَ اللَّهِ قَالَ قُلْ لَهُمْ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[23357,23357,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي عَمْرَةَ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏عَائِشَةُ بِنْتُ طَلْحَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا نُجَاهِدُ مَعَكَ فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكِ أَحْسَنُ الْجِهَادِ وَأَجْمَلُهُ الْحَجُّ حَجٌّ مَبْرُورٌ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَا أَدَعُ الْحَجَّ أَبَدًا بَعْدَ أَنْ سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23358,23358,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا تُوُفِّيَ ‏ ‏سَعْدٌ ‏ ‏وَأُتِيَ بِجِنَازَتِهِ أَمَرَتْ بِهِ ‏ ‏عَائِشَةُ ‏ ‏أَنْ يُمَرَّ بِهِ عَلَيْهَا فَشُقَّ بِهِ فِي الْمَسْجِدِ فَدَعَتْ لَهُ فَأُنْكِرَ ذَلِكَ عَلَيْهَا فَقَالَتْ مَا أَسْرَعَ النَّاسَ إِلَى الْقَوْلِ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏ابْنِ بَيْضَاءَ ‏ ‏إِلَّا فِي الْمَسْجِدِ ‏","","",""],[23359,23359,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَصَالِحِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَمَرَتْ بِجِنَازَةِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنْ يُمَرَّ بِهَا عَلَيْهَا فَمُرَّ بِهَا عَلَيْهَا فَبَلَغَهَا أَنْ قَدْ قِيلَ فِي ذَلِكَ فَقَالَتْ مَا أَسْرَعَ النَّاسَ إِلَى الْقَوْلِ وَاللَّهِ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سُهَيْلِ بْنِ بَيْضَاءَ ‏ ‏إِلَّا فِي الْمَسْجِدِ ‏","","",""],[23360,23360,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيْمَنُ بْنُ نَابِلٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قِيلَ لَهُ إِنَّ فُلَانًا وَجِعٌ لَا يَطْعَمُ الطَّعَامَ قَالَ ‏ ‏عَلَيْكُمْ ‏ ‏بِالتَّلْبِينَةِ ‏ ‏فَحَسُّوهُ إِيَّاهَا فَوَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا لَتَغْسِلُ بَطْنَ أَحَدِكُمْ كَمَا يَغْسِلُ أَحَدُكُمْ وَجْهَهُ بِالْمَاءِ مِنْ الْوَسَخِ ‏","","",""],[23361,23361,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا يَا ‏ ‏عَائِشَةُ ‏ ‏اسْتَتِرِي مِنْ النَّارِ وَلَوْ بِشِقِّ تَمْرَةٍ فَإِنَّهَا تَسُدُّ مِنْ الْجَائِعِ مَسَدَّهَا مِنْ الشَّبْعَانِ ‏","","",""],[23362,23362,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سُوَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ابْنَةَ طَلْحَةَ ‏ ‏تَذْكُرُ ‏ ‏وَذُكِرَ عِنْدَهَا الْمُحْرِمُ يَتَطَيَّبُ فَذَكَرَتْ عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهُنَّ ‏ ‏كُنَّ يَخْرُجْنَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِنَّ الضِّمَادُ قَدْ أَضْمَدْنَ قَبْلَ أَنْ يُحْرِمْنَ ثُمَّ يَغْتَسِلْنَ وَهُوَ عَلَيْهِنَّ يَعْرَقْنَ وَيَغْتَسِلْنَ لَا يَنْهَاهُنَّ عَنْهُ ‏","","",""],[23363,23363,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ هَوْذَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏أَنَّهَا حَدَّثَتْهَا ‏ ‏عَائِشَةُ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ فِي وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَيْجًا ‏ ‏حَتَّى يَرَى غَيْمًا فَإِذَا أَمْطَرَ ذَلِكَ الْغَيْمُ ذَهَبَ ذَلِكَ ‏ ‏الْهَيْجُ ‏","","",""],[23364,23364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ وَقَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏حَدَّثَهُ ‏ ‏وَكَانَتْ بَيْنَهُ وَبَيْنَ أُنَاسٍ خُصُومَةٌ فِي أَرْضٍ وَأَنَّهُ دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ ذَلِكَ لَهَا فَقَالَتْ يَا ‏ ‏أَبَا سَلَمَةَ ‏ ‏اجْتَنِبْ الْأَرْضَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ظَلَمَ ‏ ‏قِيدَ ‏ ‏شِبْرٍ مِنْ الْأَرْضِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[23365,23365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا ذُكِرَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏بِئْسَ عَبْدُ اللَّهِ أَخُو الْعَشِيرَةِ ثُمَّ دَخَلَ عَلَيْهِ فَجَعَلَ يُكَلِّمُهُ ثُمَّ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقْبِلُ عَلَيْهِ بِوَجْهِهِ حَتَّى ظَنَنْتُ أَنَّ لَهُ عِنْدَهُ مَنْزِلَةً ‏","","",""],[23366,23366,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏يُحَنَّسَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ النَّاسَ يَعْلَمُونَ مَا فِي صَلَاةِ ‏ ‏الْعَتَمَةِ ‏ ‏وَصَلَاةِ الصُّبْحِ لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏","","",""],[23367,23367,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مَعْقِلٍ الْمُحَارِبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[23368,23368,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سُئِلَتْ عَنْ صَوْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يَصُومُ شَعْبَانَ ‏ ‏وَيَتَحَرَّى ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏","","",""],[23369,23369,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ أَبُو سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَحَرَّى ‏ ‏صَوْمَ شَعْبَانَ وَصَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ ‏","","",""],[23370,23370,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَصْحَابَ هَذِهِ الصُّوَرِ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ وَيُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[23371,23371,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ إِذَا أُصِيبَ أَحَدٌ مِنْ أَهْلِهَا فَتَفَرَّقَ نِسَاءُ الْجَمَاعَةِ عَنْهَا وَبَقِيَ نِسَاءُ أَهْلِ خَاصَّتِهَا أَمَرَتْ ‏ ‏بِبُرْمَةٍ ‏ ‏مِنْ ‏ ‏تَلْبِينَةٍ ‏ ‏فَطُبِخَتْ ثُمَّ أَمَرَتْ ‏ ‏بِثَرِيدٍ ‏ ‏فَيُثْرَدُ وَصَبَّتْ ‏ ‏التَّلْبِينَةَ ‏ ‏عَلَى ‏ ‏الثَّرِيدِ ‏ ‏ثُمَّ قَالَتْ كُلُوا مِنْهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏التَّلْبِينَةَ ‏ ‏مَجَمَّةٌ ‏ ‏لِفُؤَادِ الْمَرِيضِ تُذْهِبُ بَعْضَ الْحُزْنِ ‏","","",""],[23372,23372,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي حُمَيْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي لَمْ يَقُمْ مِنْهُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏فَإِنَّهُمْ اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏قَالَتْ ‏ ‏وَلَوْلَا ذَلِكَ أُبْرِزَ قَبْرُهُ غَيْرَ أَنَّهُ خَشِيَ أَنْ يُتَّخَذَ مَسْجِدًا ‏","","",""],[23373,23373,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُسْلِمٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا ابْتَاعَ غُلَامًا فَاسْتَغَلَّهُ ثُمَّ وَجَدَ ‏ ‏أَوْ رَأَى ‏ ‏بِهِ عَيْبًا فَرَدَّهُ بِالْعَيْبِ فَقَالَ الْبَائِعُ ‏ ‏غَلَّةُ ‏ ‏عَبْدِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَلَّةُ ‏ ‏بِالضَّمَانِ ‏","","",""],[23374,23374,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَحْيَى الْغَسَّانِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَكْرِ بْنَ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏وَهُوَ عَامِلٌ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ أُتِيتُ بِسَارِقٍ فَأَرْسَلَتْ إِلَيَّ خَالَتِي ‏ ‏عَمْرَةُ بِنْتُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنْ لَا تَعْجَلَ فِي أَمْرِ هَذَا الرَّجُلِ حَتَّى آتِيَكَ فَأُخْبِرَكَ مَا سَمِعْتُ مَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي أَمْرِ السَّارِقِ قَالَ فَأَتَتْنِي وَأَخْبَرَتْنِي ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْطَعُوا فِي رُبُعِ الدِّينَارِ وَلَا تَقْطَعُوا فِيمَا هُوَ أَدْنَى مِنْ ذَلِكَ ‏ ‏وَكَانَ رُبُعُ الدِّينَارِ يَوْمَئِذٍ ‏ ‏ثَلَاثَةَ دَرَاهِمَ وَالدِّينَارُ اثْنَا عَشَرَ دِرْهَمًا قَالَ وَكَانَتْ سَرِقَتُهُ دُونَ رُبُعِ الدِّينَارِ فَلَمْ أَقْطَعْهُ ‏","","",""],[23375,23375,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏مَوْلَى ‏ ‏دَوْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ فَإِنِّي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[23376,23376,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏","","",""],[23377,23377,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ رُئِيَ هَذَا الشَّهْرُ لِتِسْعٍ وَعِشْرِينَ قَالَتْ وَمَا يُعْجِبُكُمْ مِنْ ذَاكَ لَمَا ‏ ‏صُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ ثَلَاثِينَ ‏","","",""],[23378,23378,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ يَا ‏ ‏عَائِشَةُ ‏ ‏قَوْمُكِ أَسْرَعُ أُمَّتِي بِي لَحَاقًا قَالَتْ فَلَمَّا جَلَسَ قُلْتُ يَا رَسُولَ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ لَقَدْ دَخَلْتَ وَأَنْتَ تَقُولُ كَلَامًا ذَعَرَنِي قَالَ وَمَا هُوَ قَالَتْ تَزْعُمُ أَنَّ قَوْمِي أَسْرَعُ أُمَّتِكَ بِكَ لَحَاقًا قَالَ نَعَمْ قَالَتْ وَمِمَّ ذَاكَ قَالَ تَسْتَحْلِيهِمْ ‏ ‏الْمَنَايَا ‏ ‏وَتَنَفَّسُ عَلَيْهِمْ أُمَّتُهُمْ قَالَتْ فَقُلْتُ فَكَيْفَ النَّاسُ بَعْدَ ذَلِكَ ‏ ‏أَوْ عِنْدَ ذَلِكَ ‏ ‏قَالَ ‏ ‏دَبًى ‏ ‏يَأْكُلُ شِدَادُهُ ضِعَافَهُ حَتَّى تَقُومَ عَلَيْهِمْ السَّاعَةُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏فَسَّرَهُ رَجُلٌ هُوَ ‏ ‏الْجَنَادِبُ ‏ ‏الَّتِي لَمْ تَنْبُتْ أَجْنِحَتُهَا ‏","","",""],[23379,23379,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ يَهُودِيَّةً كَانَتْ تَخْدُمُهَا فَلَا تَصْنَعُ ‏ ‏عَائِشَةُ ‏ ‏إِلَيْهَا شَيْئًا مِنْ الْمَعْرُوفِ إِلَّا قَالَتْ لَهَا الْيَهُودِيَّةُ وَقَاكِ اللَّهُ عَذَابَ الْقَبْرِ قَالَتْ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ فَقُلْتُ يَا رَسُولَ اللَّهِ هَلْ لِلْقَبْرِ عَذَابٌ قَبْلَ يَوْمِ الْقِيَامَةِ قَالَ لَا وَعَمَّ ذَاكَ قَالَتْ هَذِهِ الْيَهُودِيَّةُ لَا نَصْنَعُ إِلَيْهَا مِنْ الْمَعْرُوفِ شَيْئًا إِلَّا قَالَتْ وَقَاكِ اللَّهُ عَذَابَ الْقَبْرِ قَالَ كَذَبَتْ يَهُودُ وَهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ كُذُبٌ لَا عَذَابَ دُونَ يَوْمِ الْقِيَامَةِ قَالَتْ ثُمَّ مَكَثَ بَعْدَ ذَاكَ مَا شَاءَ اللَّهُ أَنْ يَمْكُثَ فَخَرَجَ ذَاتَ يَوْمٍ نِصْفَ النَّهَارِ ‏ ‏مُشْتَمِلًا ‏ ‏بِثَوْبِهِ مُحْمَرَّةً عَيْنَاهُ وَهُوَ ‏ ‏يُنَادِي بِأَعْلَى صَوْتِهِ أَيُّهَا النَّاسُ ‏ ‏أَظَلَّتْكُمْ الْفِتَنُ كَقِطَعِ اللَّيْلِ الْمُظْلِمِ أَيُّهَا النَّاسُ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا وَضَحِكْتُمْ قَلِيلًا أَيُّهَا النَّاسُ اسْتَعِيذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ فَإِنَّ عَذَابَ الْقَبْرِ حَقٌّ ‏","","",""],[23380,23380,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنْ كُنْتُ لَأَدْخُلُ الْبَيْتَ لِلْحَاجَةِ وَالْمَرِيضُ فِيهِ فَمَا أَسْأَلُ عَنْهُ إِلَّا وَأَنَا مَارَّةٌ وَإِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُدْخِلُ عَلَيَّ رَأْسَهُ وَهُوَ فِي الْمَسْجِدِ ‏ ‏فَأُرَجِّلُهُ ‏ ‏وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةٍ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏إِذَا كَانَ ‏ ‏مُعْتَكِفًا ‏","","",""],[23381,23381,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏جَاءَتْ ‏ ‏عَائِشَةَ ‏ ‏تَسْتَعِينُهَا فِي ‏ ‏كِتَابَتِهَا ‏ ‏وَلَمْ تَكُنْ قَضَتْ مِنْ ‏ ‏كِتَابَتِهَا ‏ ‏شَيْئًا فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏ارْجِعِي إِلَى أَهْلِكِ فَإِنْ أَحَبُّوا أَنْ ‏ ‏أَقْضِيَ ‏ ‏عَنْكِ ‏ ‏كِتَابَتَكِ ‏ ‏وَيَكُونَ ‏ ‏وَلَاؤُكِ ‏ ‏لِي فَعَلْتُ فَذَكَرَتْ ذَلِكَ ‏ ‏بَرِيرَةُ ‏ ‏لِأَهْلِهَا فَأَبَوْا وَقَالُوا إِنْ شَاءَتْ أَنْ ‏ ‏تَحْتَسِبَ ‏ ‏عَلَيْكِ فَلْتَفْعَلْ وَلْيَكُنْ لَنَا وَلَاؤُكِ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْتَاعِي ‏ ‏فَأَعْتِقِي فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ قَالَتْ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا بَالُ أُنَاسٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ مَنْ اشْتَرَطَ شَرْطًا لَيْسَ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ فَلَيْسَ لَهُ وَإِنْ شَرَطَ مِائَةَ مَرَّةٍ شَرْطُ اللَّهِ عَزَّ وَجَلَّ أَحَقُّ وَأَوْثَقُ ‏","","",""],[23382,23382,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏اسْتَفْتَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي ‏ ‏أُسْتَحَاضُ ‏ ‏قَالَ إِنَّمَا ذَاكَ ‏ ‏عِرْقٌ ‏ ‏فَاغْتَسِلِي ثُمَّ صَلِّي فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏لَمْ يَأْمُرْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ إِنَّمَا فَعَلَتْهُ هِيَ ‏","","",""],[23383,23383,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهْدِي ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَأَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏بُدْنِهِ ثُمَّ لَا يَجْتَنِبُ شَيْئًا مِمَّا يَجْتَنِبُهُ الْمُحْرِمُ ‏","","",""],[23384,23384,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَعُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏حَاضَتْ ‏ ‏صَفِيَّةُ بِنْتُ حُيَىٍّ ‏ ‏بَعْدَمَا ‏ ‏أَفَاضَتْ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَذَكَرَتْ حَيْضَهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَابِسَتُنَا ‏ ‏هِيَ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّهَا قَدْ ‏ ‏أَفَاضَتْ ‏ ‏وَطَافَتْ ‏ ‏بِالْبَيْتِ ‏ ‏ثُمَّ حَاضَتْ بَعْدَ ‏ ‏الْإِفَاضَةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْتَنْفِرْ ‏","","",""],[23385,23385,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيَّ مَسْرُورًا ‏ ‏تَبْرُقُ ‏ ‏أَسَارِيرُ ‏ ‏وَجْهِهِ قَالَ أَلَمْ تَرَيْ أَنَّ ‏ ‏مُجَزِّزًا ‏ ‏نَظَرَ ‏ ‏آنِفًا ‏ ‏إِلَى ‏ ‏زَيْدِ بْنِ حَارِثَةَ ‏ ‏وَأُسَامَةَ ‏ ‏فَقَالَ ‏ ‏إِنَّ بَعْضَ الْأَقْدَامِ لَمِنْ بَعْضٍ ‏","","",""],[23386,23386,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ كَيْسَانَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَمْرَةُ بِنْتُ قَيْسٍ الْعَدَوِيَّةُ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَارُّ مِنْ الطَّاعُونِ كَالْفَارِّ مِنْ ‏ ‏الزَّحْفِ ‏","","",""],[23387,23387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْتَهِدُ فِي ‏ ‏الْعَشْرِ ‏ ‏مَا لَا يَجْتَهِدُ فِي غَيْرِهِ ‏","","",""],[23388,23388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ الطُّفَيْلِ بْنِ سَخْبَرَةَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَعْظَمَ النِّكَاحِ بَرَكَةً أَيْسَرُهُ ‏ ‏مُؤْنَةً ‏","","",""],[23389,23389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهَا ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي فَرَعَةٍ مِنْ الْغَنَمِ مِنْ الْخَمْسَةِ وَاحِدَةٌ ‏","","",""],[23390,23390,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ هِنْدٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ ‏ ‏السَّبْعَ ‏ ‏الْأُوَلَ مِنْ الْقُرْآنِ فَهُوَ ‏ ‏حَبْرٌ ‏","","",""],[23391,23391,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَعَكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَبِلَالٌ ‏ ‏فَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏إِذَا أَخَذَتْهُ ‏ ‏الْحُمَّى ‏ ‏قَالَ ‏ ‏كُلُّ امْرِئٍ مُصَبَّحٌ فِي أَهْلِهِ ‏ ‏وَالْمَوْتُ أَدْنَى مِنْ شِرَاكِ نَعْلِهِ ‏ ‏وَكَانَ ‏ ‏بِلَالٌ ‏ ‏إِذَا ‏ ‏أَقْلَعَ ‏ ‏عَنْهُ تَغَنَّى فَقَالَ ‏ ‏أَلَا لَيْتَ شِعْرِي هَلْ أَبِيتَنَّ لَيْلَةً ‏ ‏بِوَادٍ وَحَوْلِي إِذْخِرٌ ‏ ‏وَجَلِيلُ ‏ ‏وَهَلْ أَرِدْنَ يَوْمًا مِيَاهَ ‏ ‏مَجَنَّةٍ ‏ ‏وَهَلْ يَبْدُوَنْ لِي شَامَةٌ وَطَفِيلُ ‏ ‏اللَّهُمَّ اخْزِ ‏ ‏عُتْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَأُمَيَّةَ بْنَ خَلَفٍ ‏ ‏كَمَا أَخْرَجُونَا مِنْ ‏ ‏مَكَّةَ ‏","","",""],[23392,23392,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَعِبَتْ ‏ ‏الْحَبَشَةُ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَجِئْتُ أَنْظُرُ ‏ ‏فَجَعَلَ يُطَأْطِئُ لِي ‏ ‏مَنْكِبَيْهِ ‏ ‏لِأَنْظُرَ إِلَيْهِمْ ‏","","",""],[23393,23393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏سَائِبَةُ ‏ ‏مَوْلَاةٌ ‏ ‏لِلْفَاكِهِ بْنِ الْمُغِيرَةِ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَرَأَيْتُ فِي بَيْتِهَا رُمْحًا مَوْضُوعًا قُلْتُ يَا أُمَّ الْمُؤْمِنِينَ مَا تَصْنَعُونَ بِهَذَا الرُّمْحِ قَالَتْ هَذَا لِهَذِهِ الْأَوْزَاغِ نَقْتُلُهُنَّ بِهِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏حِينَ أُلْقِيَ فِي النَّارِ لَمْ تَكُنْ فِي الْأَرْضِ دَابَّةٌ إِلَّا تُطْفِئُ النَّارَ عَنْهُ غَيْرَ ‏ ‏الْوَزَغِ ‏ ‏كَانَ يَنْفُخُ عَلَيْهِ فَأَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِهِ ‏","","",""],[23394,23394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مَوْلَاةٌ لِلْفَاكِهِ بْنِ الْمُغِيرَةِ الْمَخْزُومِيِّ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِ ‏ ‏الْجِنَّانِ ‏ ‏الَّتِي تَكُونُ فِي الْبُيُوتِ غَيْرَ ذِي ‏ ‏الطُّفْيَتَيْنِ ‏ ‏وَالْبَتْرَاءِ فَإِنَّهُمَا تَطْمِسَانِ الْأَبْصَارَ وَتَقْتُلَانِ أَوْلَادَ الْحَبَالَى فِي بُطُونِهِمْ فَمَنْ لَمْ يَقْتُلْهُمَا فَلَيْسَ مِنَّا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بِهِمَا ‏ ‏حَسَنٌ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏الْمَعْنَى وَالْإِسْنَادُ عَنْ عَنْ ‏","","",""],[23395,23395,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ ‏ ‏يُضَاهُونَ ‏","","",""],[23396,23396,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِيمَا بَيْنَ عِشَاءِ الْآخِرَةِ إِلَى أَنْ يَنْصَدِعَ الْفَجْرُ إِحْدَى عَشْرَةَ رَكْعَةً يُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ ‏ ‏وَيُوتِرُ ‏ ‏بِوَاحِدَةٍ وَيَمْكُثُ فِي سُجُودِهِ بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ بِخَمْسِينَ آيَةً فَإِذَا سَكَتَ الْمُؤَذِّنُ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ ‏","","",""],[23397,23397,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏وَهِيَ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏سَبْعَ سِنِينَ فَشَكَتْ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا لَيْسَتْ بِالْحَيْضَةِ وَإِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَدَعِي الصَّلَاةَ وَإِذَا ‏ ‏أَدْبَرَتْ ‏ ‏فَاغْتَسِلِي ثُمَّ صَلِّي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ ثُمَّ تُصَلِّي وَكَانَتْ تَقْعُدُ فِي ‏ ‏مِرْكَنٍ ‏ ‏لِأُخْتِهَا ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏حَتَّى أَنَّ حُمْرَةَ الدَّمِ ‏ ‏لَتَعْلُو الْمَاءَ ‏","","",""],[23398,23398,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زَبَّانُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي الْحُجْرَةِ وَأَنَا فِي الْبَيْتِ فَيَفْصِلُ بَيْنَ الشَّفْعِ ‏ ‏وَالْوَتْرِ ‏ ‏بِتَسْلِيمٍ يُسْمِعُنَاهُ ‏","","",""],[23399,23399,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُذُوا مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمَلُّ حَتَّى تَمَلُّوا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَكَانَ أَحَبُّ الصَّلَاةِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ وَ ‏ { ‏الَّذِينَ هُمْ عَلَى صَلَاتِهِمْ دَائِمُونَ ‏}","","",""],[23400,23400,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا ‏ ‏جَارِيَتَانِ فِي أَيَّامِ ‏ ‏مِنًى ‏ ‏تَضْرِبَانِ بِدُفَّيْنِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسَجًّى ‏ ‏عَلَيْهِ بِثَوْبِهِ فَانْتَهَرَهُمَا فَكَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجْهَهُ فَقَالَ ‏ ‏دَعْهُنَّ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَإِنَّهَا أَيَّامُ عِيدٍ ‏","","",""]];
